-- River Fishing Challenge: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'river_fishing', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["fish-01",1,"Bình Minh Trên Hồ Ngọc","Video đứng trên thuyền nhôm câu cá giữa hồ xanh ngọc, nước trong nhìn thấy đáy; file mục II.2.","Sáng sớm, bác Năm ngư dân dẫn cả lớp ra bến gỗ, chia mỗi nhóm một thuyền nhôm nhỏ và một cây cần gỗ cũ. Bác kể rằng hồ Ngọc có sáu loài cá thường gặp và một truyền thuyết: Cá Hồi Hoàng Gia chỉ ngoi lên khi mặt trời vừa ló khỏi đỉnh núi. Các thuyền phải học cách quăng cần, chờ phao chìm và giữ thanh căng dây, rồi điền vào Sổ Câu Cá đủ các loài cá của hồ. Câu đúng giúp nâng cần, đổi mồi, và cá lớn sẽ tìm đến. Khi ánh nắng đầu tiên chạm mặt hồ, thuyền nào có cần vàng sẽ có cơ hội gặp Cá Hồi Hoàng Gia.","Hồ xanh ngọc dưới chân núi lúc bình minh, sương mỏng trên mặt nước, rừng thông soi bóng. Mặt hồ phẳng lặng, nhìn thấy đá cuội và đàn cá nhỏ dưới đáy. Bên cạnh thuyền nhôm là một chiếc thuyền chèo trắng có lưới vàng và phao cứu sinh treo cạnh bến.",[{"n":1,"title":"Ra bến, lên thuyền","minutes":5,"optional":false,"goal":"Nhận thuyền, áo phao, cần gỗ; chèo ra giữa hồ.","beats":["Bác Năm dạy 3 bước: quăng, chờ, kéo.","Mỗi câu đúng là một nhịp chèo ra vị trí neo.","Bác Năm chỉ chiếc thuyền chèo cũ của ông: mỗi món trên thuyền đọc đúng tên được một mồi giun.","Cần câu gỗ cấp một của bác Năm: cầm đúng tay mới quăng được.","Giá gác cần và ghế gấp trên thuyền: gọi đúng tên đồ nghề để ngồi vào chỗ."],"question_hook":"Câu hỏi trên mái chèo; câu đúng đưa thuyền ra khu cá nhiều hơn.","reward":"Cần gỗ + mồi giun.","vocab":["boat","paddle","life jacket","rod","rowboat","net","lifebuoy","wooden rod","beginner","rod holder","boat chair"],"assets":["river_dock","river_boat_aluminium","kayak_lifejacket","fish_rod","fish_bait","hdri_dawn","river_boat_row","river_buoy","fish_rod_wood","fish_rod_holder","fish_boat_chair"]},{"n":2,"title":"Cú quăng đầu tiên","minutes":5,"optional":false,"goal":"Học quăng cần bằng Thanh lực quăng, bắt con cá đầu tiên.","beats":["Thanh lực quăng: dừng đúng vùng xanh để phao rơi xa.","Cá rô phi và cá rô đồng cắn câu nhiều."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá đầu tiên vào Sổ Câu Cá.","vocab":["cast","float","bite","pull"],"assets":["fish_bobber","fish_reel","fish_hook","fish_tilapia","fish_climbing_perch","anim_cast"]},{"n":3,"title":"Đổi mồi, đổi chỗ","minutes":5,"optional":false,"goal":"Thử mồi tôm và mồi cá nhỏ để bắt cá chép, cá diếc.","beats":["Mồi khác nhau gọi loài khác nhau.","Sau 3 câu đúng: nâng cần sợi thủy tinh."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần sợi thủy tinh.","vocab":["bait","worm","shrimp","change"],"assets":["fish_bait","fish_carp","fish_crucian","fish_tackle_box"]},{"n":4,"title":"Khúc sâu gần bãi đá","minutes":5,"optional":false,"goal":"Neo thuyền gần bãi đá, săn cá trắm và cá lóc.","beats":["Cá lớn kéo mạnh, thanh căng dây rung nhiều.","Vợt cần người thứ hai trên thuyền trả lời đúng."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Cá to cần 2 câu đúng liên tiếp.","reward":"Vợt + cần carbon.","vocab":["deep","strong","net","heavy"],"assets":["fish_grass_carp","fish_snakehead","fish_net","river_rock_large"]},{"n":5,"title":"Cân và ghi kỷ lục","minutes":5,"optional":false,"goal":"Về bến cân cá, ghi Sổ Câu Cá, thả cá lại hồ.","beats":["Bảng kỷ lục xếp hạng theo điểm.","Câu đúng mở khóa \"sự thật về loài cá\".","Cá được bỏ vào giỏ đan trước khi cân.","Cá tuyết nhỏ nằm trong thùng cá trước khi cân: đọc tên cá trên nhãn thùng."],"question_hook":"Câu hỏi hiện trên bảng cân; đúng thì cân chính xác và cộng điểm thưởng.","reward":"Cần vàng cho 3 thuyền dẫn đầu và mọi em đủ 9 câu đúng.","vocab":["weigh","record","release","kilogram","basket","cod","fish box"],"assets":["fish_scale","fish_record_board","fish_bucket","river_dock","fish_basket","fish_cod","fish_box"]},{"n":6,"title":"Mặt trời ló núi","minutes":5,"optional":false,"goal":"Cơ hội gặp Cá Hồi Hoàng Gia cho ai có cần vàng.","beats":["Nắng đầu tiên chạm mặt hồ, cá hồi lấp lánh bên dưới.","Cá Cực hiếm cần 3 câu đúng liên tiếp, câu cuối khó nhất."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Danh hiệu \"Ngư Phủ Bình Minh\"; người bắt cá to nhất là MVP.","vocab":["sunrise","legend","rare","shine"],"assets":["fish_king_salmon","fish_rod","hdri_noon","anim_pull_fish","anim_cheer"]},{"n":7,"title":"Chặng phụ: Cá trê dưới bến","minutes":5,"optional":true,"goal":"Kéo dài: câu cá trê lẩn dưới bến gỗ.","beats":["Cá trê chỉ cắn mồi giun sát đáy."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["catfish","under","bottom"],"assets":["fish_walking_catfish","river_dock"]},{"n":8,"title":"Chặng phụ: Sổ tay loài cá","minutes":5,"optional":true,"goal":"Viết một câu mô tả mỗi loài cá đã bắt.","beats":["Sổ tay in ra gửi phụ huynh."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết ngắn, không tính thua.","reward":"Huy hiệu \"Nhà Sinh Vật Nhí\".","vocab":["scale","fin","color","long"],"assets":["fish_record_board"]}],{},["anim_cast","anim_cheer","anim_pull_fish","fish_bait","fish_basket","fish_boat_chair","fish_bobber","fish_box","fish_bucket","fish_carp","fish_climbing_perch","fish_cod","fish_crucian","fish_grass_carp","fish_hook","fish_king_salmon","fish_net","fish_record_board","fish_reel","fish_rod","fish_rod_holder","fish_rod_wood","fish_scale","fish_snakehead","fish_tackle_box","fish_tilapia","fish_walking_catfish","hdri_dawn","hdri_noon","kayak_lifejacket","river_boat_aluminium","river_boat_row","river_buoy","river_dock","river_rock_large"]],["fish-02",2,"Giải Câu Cá Mùa Hè Bến Gỗ","Video bến cầu gỗ đưa ra nước; file: tính điểm theo kích thước và độ hiếm.","Trại tổ chức Giải Câu Cá Mùa Hè, phát thanh viên vui tính Bé Bự bình luận trực tiếp qua loa. Mỗi thuyền có 30 phút qua ba vòng: vòng loại ở bến, vòng bán kết giữa sông, vòng chung kết ở khúc sâu. Luật giải rất rõ: điểm theo cân nặng và độ hiếm, thả cá lại sau khi cân, và thuyền nào câu được loài mới sẽ có điểm thưởng. Giữa giải, đội vô địch năm ngoái của Captain Ray tuyên bố sẽ bảo vệ ngôi vương. Chung kết là cuộc săn cá lăng, loài cá hiếm của khúc sông sâu, và ai bắt được sẽ được khắc tên lên cúp gỗ.","Bến gỗ dài đưa ra sông, cờ giải đấu tung bay, bảng điểm lớn trên bờ, khán giả cổ vũ. Nắng sáng rực rỡ, nước sông xanh trong, gió nhẹ. Phao cứu sinh ngăn làn thi và thuyền chèo của ban tổ chức neo cạnh bến. Năm cần câu thi đấu bày trên giá ở bến, người dẫn chương trình chờ khai mạc.",[{"n":1,"title":"Khai mạc","minutes":5,"optional":false,"goal":"Đăng ký thuyền, nhận số áo, chọn cần và mồi xuất phát.","beats":["Bé Bự giới thiệu từng thuyền.","Mỗi câu đúng chọn thêm một món đồ nghề.","Năm cần câu thi đấu bày ra, mỗi đội bốc thăm một cần: nối đúng tên bộ phận trên cần để chọn."],"question_hook":"Câu hỏi trên bảng đăng ký.","reward":"Bộ đồ nghề xuất phát.","vocab":["contest","team","start","number","rod","lucky draw"],"assets":["river_dock","river_sign","fish_tackle_box","fish_rod","camp_bunting","rod_cand_1","rod_cand_2","rod_cand_3","rod_cand_4","rod_cand_5","char_female_b"]},{"n":2,"title":"Vòng loại ở bến","minutes":5,"optional":false,"goal":"Câu cá thường ở bến, đạt 300 điểm để vào vòng sau.","beats":["Cá rô phi, cá chép, cá diếc nhiều.","Bảng điểm cập nhật trực tiếp.","Phao ngăn làn: thuyền nào vượt phao khi chưa trả lời đúng bị trừ điểm.","Cá rô biển ở vòng loại cắn mồi: đọc đúng tên mồi để quăng trúng.","Bến nổi trên thùng phuy xanh là nơi xếp hàng vòng loại: đọc đúng luật thi trước khi bước lên."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Vé bán kết.","vocab":["qualify","points","score","catch","lane","lifebuoy","bass","qualifying","floating dock","rope"],"assets":["fish_tilapia","fish_carp","fish_crucian","fish_record_board","river_buoy","fish_bass","fish_floating_dock"]},{"n":3,"title":"Bán kết giữa sông","minutes":5,"optional":false,"goal":"Chèo ra giữa sông, săn cá basa và cá tra.","beats":["Dòng chảy đẩy thuyền: câu đúng giữ thuyền đứng yên.","Nâng cần sợi thủy tinh sau 3 câu đúng.","Thuyền trọng tài đi giữa sông chấm cá bán kết.","Cá mè bạc xuất hiện ở bán kết: nhìn màu vảy để đoán đúng tên.","Cần sợi thủy tinh của vòng bán kết: mỗi câu đúng giúp đổi đúng mồi."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần sợi thủy tinh, vé chung kết.","vocab":["current","middle","basa","steady","referee boat","net","silver carp","semi-final","fiberglass rod","reel"],"assets":["fish_basa","fish_tra","river_boat_aluminium","river_buoy","river_boat_row","fish_silver_carp","fish_rod_fiberglass"]},{"n":4,"title":"Thách đấu Captain Ray","minutes":5,"optional":false,"goal":"Đối đầu trực tiếp với thuyền vô địch năm ngoái (thuyền máy điều khiển).","beats":["Ai bắt nhiều điểm hơn trong 5 phút thắng.","Captain Ray câu nhanh theo mức độ khó của lớp.","Captain Ray thách bằng cần carbon đen: đọc đúng các bộ phận của cần để nhận thách đấu."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Mỗi câu đúng trước Captain Ray cướp được một con cá khỏi lưỡi của ông.","reward":"Cần carbon.","vocab":["challenge","faster","beat","champion","carbon rod"],"assets":["fish_snakehead","fish_rainbow_trout","river_boat_aluminium","fish_rod_carbon"]},{"n":5,"title":"Chung kết khúc sâu","minutes":5,"optional":false,"goal":"Săn cá lăng ở khúc sông sâu.","beats":["Cá lăng hiếm, kéo rất mạnh.","Cả thuyền cùng trả lời để giữ dây.","Cá chung kết được đặt trong giỏ đan trước bảng điểm."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Cá hiếm cần 2 câu đúng liên tiếp.","reward":"Cá lăng vào bảng kỷ lục.","vocab":["final","rare","deep","hold","basket","record"],"assets":["fish_hemibagrus","fish_net","fish_rod","anim_pull_fish","fish_basket"]},{"n":6,"title":"Lễ trao cúp","minutes":5,"optional":false,"goal":"Cân cá cuối, công bố thuyền vô địch và MVP.","beats":["Tên người thắng khắc lên cúp gỗ.","Cá được thả lại sông.","Chiếc cần vàng là phần thưởng của nhà vô địch, đặt cạnh chiếc cúp."],"question_hook":"Câu hỏi trên bục trao giải (phỏng vấn ngắn).","reward":"Cúp gỗ + danh hiệu \"Vua Bến Gỗ\".","vocab":["winner","trophy","congratulations","release","gold rod"],"assets":["fish_scale","fish_record_board","river_dock","anim_cheer","fish_rod_gold"]},{"n":7,"title":"Chặng phụ: Giải phụ cá nhỏ nhất","minutes":5,"optional":true,"goal":"Kéo dài: giải vui cho con cá nhỏ nhất.","beats":["Cá nhỏ nhất cũng được thưởng."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["small","tiny","funny"],"assets":["fish_climbing_perch"]},{"n":8,"title":"Chặng phụ: Phỏng vấn nhà vô địch","minutes":5,"optional":true,"goal":"Mỗi thuyền trả lời phỏng vấn tiếng Anh của Bé Bự.","beats":["Câu trả lời hay phát lại trên loa."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu nói/viết ngắn, không tính thua.","reward":"Huy hiệu \"Ngôi Sao Giải Đấu\".","vocab":["proud","teamwork","next year"],"assets":["river_sign"]}],{"note":"Captain Ray là thuyền máy do máy chủ điều khiển, độ khó theo bậc của lớp."},["anim_cheer","anim_pull_fish","camp_bunting","char_female_b","fish_basa","fish_basket","fish_bass","fish_carp","fish_climbing_perch","fish_crucian","fish_floating_dock","fish_hemibagrus","fish_net","fish_rainbow_trout","fish_record_board","fish_rod","fish_rod_carbon","fish_rod_fiberglass","fish_rod_gold","fish_scale","fish_silver_carp","fish_snakehead","fish_tackle_box","fish_tilapia","fish_tra","river_boat_aluminium","river_boat_row","river_buoy","river_dock","river_sign","rod_cand_1","rod_cand_2","rod_cand_3","rod_cand_4","rod_cand_5"]],["fish-03",3,"Chân Thác Và Cá Lăng Sông Sâu","File: đoạn sông ngọc chảy qua chân núi; video nước trong và vách đá.","Thầy Quang, huấn luyện viên câu cá thể thao, đưa nhóm câu giỏi nhất trại lên chân thác lớn. Ở đây nước chảy mạnh, cá khỏe, chỉ người giữ được thanh căng dây thật vững mới thắng được. Thầy giao một thử thách: bắt đủ ba loài cá sông sâu (cá lăng, cá nheo, cá chình) để được vào \"Câu lạc bộ Chân Thác\". Nhưng dòng nước thay đổi theo giờ, và thuyền phải di chuyển giữa ba vũng nước khác nhau theo bản đồ dòng chảy. Cuối buổi, cả nhóm sẽ thả một con cá lăng thật lớn trở lại vũng sâu, như lời hứa giữ gìn dòng sông.","Khúc sông dưới chân thác lớn, nước xoáy trắng bọt rồi chảy chậm thành vùng sâu xanh thẫm. Vách đá cao hai bên, chim én bay quanh thác, bụi nước lấp lánh. Thung lũng sông nhìn từ trên cao làm bản đồ dòng chảy; thác cao đổ xuống vũng xanh, bọt trắng nổi đầy.",[{"n":1,"title":"Bản đồ dòng chảy","minutes":5,"optional":false,"goal":"Đọc bản đồ dòng chảy, chọn vũng nước đầu tiên.","beats":["Ba vũng: Vũng Bọt, Vũng Xanh, Vũng Đá.","Chọn sai thì nước xoáy đẩy thuyền ra.","Bản đồ nổi của thung lũng sông: ghim ba vũng cá vào đúng chỗ."],"question_hook":"Câu hỏi trên bản đồ dòng chảy.","reward":"Vị trí neo an toàn.","vocab":["current","fast","slow","pool","map","waterfall"],"assets":["surv_map","river_boat_aluminium","water_foam","river_cliff","mini_ganga_valley","river_waterfall"]},{"n":2,"title":"Neo thuyền trong nước xiết","minutes":5,"optional":false,"goal":"Thả neo và giữ thuyền ổn định.","beats":["Thanh cân bằng thuyền: câu đúng giữ thuyền không xoay.","Chân thác nước xiết: thả neo đúng chỗ thì thuyền không trôi."],"question_hook":"Câu hỏi trên sợi dây neo; đúng thì neo bám đá.","reward":"Thuyền đứng vững.","vocab":["anchor","stay","balance","rope","rapids"],"assets":["camp_rope","river_rock_large","river_buoy","river_waterfall_pool"]},{"n":3,"title":"Vũng Bọt: cá nheo","minutes":5,"optional":false,"goal":"Câu cá nheo trong vũng nước trắng bọt.","beats":["Cá nheo kéo ngang, thanh căng dây lắc trái phải.","Vũng Bọt: bong bóng nổi lên là dấu cá nheo ở dưới."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá nheo + cần carbon.","vocab":["pull","side","strong","whiskers","foam","bubble"],"assets":["fish_sheatfish","fish_rod","anim_pull_fish","fx_bubbles"]},{"n":4,"title":"Vũng Xanh: cá lăng","minutes":5,"optional":false,"goal":"Câu cá lăng trong vùng sâu xanh thẫm.","beats":["Cá lăng hiếm, cần 2 câu đúng liên tiếp.","Cá lăng nhiều màu chỉ ngoi lên ở Vũng Xanh."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá lăng.","vocab":["deep","patient","rare","wait","hemibagrus","deep pool"],"assets":["fish_hemibagrus","fish_bait","water_normal"]},{"n":5,"title":"Vũng Đá: cá chình","minutes":5,"optional":false,"goal":"Câu cá chình ẩn trong khe đá.","beats":["Cá chình chui vào khe: phải kéo đúng lúc."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Câu dạng sắp xếp: xếp đúng các bước kéo cá ra khỏi khe.","reward":"Cá chình.","vocab":["eel","hide","rock","slippery"],"assets":["fish_eel","river_rock_medium","fish_net"]},{"n":6,"title":"Câu lạc bộ Chân Thác","minutes":5,"optional":false,"goal":"Đủ ba loài: vào câu lạc bộ, thả cá lăng lớn về vũng sâu.","beats":["Lễ thả cá dưới cầu vồng thác.","MVP: người có tổng cân cao nhất."],"question_hook":"Câu lời hứa bảo vệ dòng sông (chọn câu đúng ngữ pháp).","reward":"Huy hiệu \"Câu Lạc Bộ Chân Thác\".","vocab":["protect","promise","river","nature"],"assets":["fish_hemibagrus","hdri_noon","anim_cheer"]},{"n":7,"title":"Chặng phụ: Cá hồi vân","minutes":5,"optional":true,"goal":"Kéo dài: cá hồi vân bơi ngược thác.","beats":["Cá nhảy khỏi mặt nước."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["jump","upstream"],"assets":["fish_rainbow_trout"]},{"n":8,"title":"Chặng phụ: Biển báo bảo vệ","minutes":5,"optional":true,"goal":"Viết biển báo tiếng Anh bảo vệ dòng sông.","beats":["Biển báo cắm ở chân thác."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.","reward":"Huy hiệu \"Người Giữ Sông\".","vocab":["do not","please","keep clean"],"assets":["river_sign"]}],{"note":"Ba vũng nước = ba khu; thuyền xoay vòng khu mỗi 5 phút để lớp đông không chen một vũng."},["anim_cheer","anim_pull_fish","camp_rope","fish_bait","fish_eel","fish_hemibagrus","fish_net","fish_rainbow_trout","fish_rod","fish_sheatfish","fx_bubbles","hdri_noon","mini_ganga_valley","river_boat_aluminium","river_buoy","river_cliff","river_rock_large","river_rock_medium","river_sign","river_waterfall","river_waterfall_pool","surv_map","water_foam","water_normal"]],["fish-04",4,"Đêm Trăng Câu Cá Tra","Video hồ và rừng thông; ý tưởng câu cá đêm với đèn lồng, phao phát sáng.","Đêm trăng tròn, chú Tâm mở chuyến \"Câu đêm Trăng Rằm\" vì cá tra và cá basa chỉ ăn mồi nhiều vào ban đêm. Mỗi thuyền được phát một đèn lồng và những chiếc phao phát sáng, cá cắn câu thì phao lóe sáng. Nhưng giữa đêm, một đám sương dày trôi qua che mất trăng, đèn lồng của vài thuyền tắt. Các thuyền phải giúp nhau thắp lại đèn, đọc dấu sao để tìm đường về các bãi cá. Gần nửa đêm, mặt sông sáng lên vì đàn cá tra lớn bơi qua, đó là lúc tranh tài cuối cùng.","Sông rộng về đêm, trăng tròn, đèn lồng treo trên mũi thuyền, phao phát sáng xanh lá trên mặt nước. Tiếng ếch nhái, gió mát, đom đóm ven bờ.",[{"n":1,"title":"Thắp đèn mũi thuyền","minutes":5,"optional":false,"goal":"Thắp đèn lồng, buộc phao phát sáng.","beats":["Mỗi câu đúng thắp sáng một phao.","Đèn trụ bến sáng ấm: thắp đèn mũi thuyền bằng cách đọc đúng tên từng bộ phận của đèn."],"question_hook":"Câu hỏi trên chiếc đèn lồng.","reward":"Đèn + phao sáng.","vocab":["lantern","glow","moon","night","lamp"],"assets":["camp_lantern","fish_bobber","river_boat_aluminium","hdri_night","fish_dock_lamp"]},{"n":2,"title":"Cá đêm đầu tiên","minutes":5,"optional":false,"goal":"Câu cá basa dưới ánh trăng.","beats":["Phao lóe sáng khi cá cắn.","Một con cá lạ ánh bạc chưa ai biết tên: cả đội đoán đặc điểm để đặt tên cho nó."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá basa.","vocab":["bite","flash","quiet","basa","mystery","night fish"],"assets":["fish_basa","fish_reel","anim_cast","fish_unknown"]},{"n":3,"title":"Mồi đêm","minutes":5,"optional":false,"goal":"Đổi mồi phù hợp cá đêm (mồi tôm, mồi cám).","beats":["Nâng cần sau 3 câu đúng."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần sợi thủy tinh + mồi tôm.","vocab":["shrimp","smell","choose"],"assets":["fish_bait","fish_tackle_box"]},{"n":4,"title":"Sương che trăng","minutes":5,"optional":false,"goal":"Đèn tắt: giúp thuyền bên cạnh thắp lại, dựa vào sao tìm bãi cá.","beats":["Câu đúng của thuyền này thắp đèn cho thuyền kia.","Sao Bắc Đẩu chỉ hướng bãi cá."],"question_hook":"Câu hỏi trên ngọn đèn của thuyền bạn; hợp câu hướng (north, east).","reward":"Cả lớp sáng đèn lại.","vocab":["fog","help","star","direction"],"assets":["camp_lantern","hdri_night","surv_compass"]},{"n":5,"title":"Cá trê và cá lóc ven bờ","minutes":5,"optional":false,"goal":"Câu sát bờ lau, cá trê và cá lóc ra kiếm ăn.","beats":["Lau sậy rung khi cá đến."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần carbon.","vocab":["shore","reed","snakehead","catfish"],"assets":["fish_walking_catfish","fish_snakehead","river_reed"]},{"n":6,"title":"Đàn cá tra nửa đêm","minutes":5,"optional":false,"goal":"Mặt sông sáng lên, tranh tài câu cá tra lớn.","beats":["Cá tra lớn cần 2 câu đúng liên tiếp.","MVP: cá nặng nhất đêm."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Danh hiệu \"Ngư Phủ Trăng Rằm\".","vocab":["midnight","big","school of fish","win"],"assets":["fish_tra","fish_net","anim_pull_fish","anim_cheer"]},{"n":7,"title":"Chặng phụ: Cá chình đêm","minutes":5,"optional":true,"goal":"Kéo dài: cá chình ra khỏi hang ban đêm.","beats":["Rất trơn, khó giữ."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["eel","slippery"],"assets":["fish_eel"]},{"n":8,"title":"Chặng phụ: Thơ trăng","minutes":5,"optional":true,"goal":"Viết hai câu thơ tiếng Anh về trăng và sông.","beats":["Thơ hay đọc trên loa trại."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.","reward":"Huy hiệu \"Thi Sĩ Sông Trăng\".","vocab":["moonlight","silver","calm"],"assets":["hdri_night"]}],{},["anim_cast","anim_cheer","anim_pull_fish","camp_lantern","fish_bait","fish_basa","fish_bobber","fish_dock_lamp","fish_eel","fish_net","fish_reel","fish_snakehead","fish_tackle_box","fish_tra","fish_unknown","fish_walking_catfish","hdri_night","river_boat_aluminium","river_reed","surv_compass"]],["fish-05",5,"Truyền Thuyết Vua Cá Hồi","File: Cá Hồi Hoàng Gia (cá MVP), nâng cấp cần và mồi để săn cá khổng lồ; video câu cá trên thuyền.","Ông Chài Tư giữ một cuốn sổ cũ ghi về Vua Cá Hồi, con cá hồi hoàng gia khổng lồ chưa ai bắt được trong 30 năm. Sổ chép ba manh mối bằng tiếng Anh từ một nhà thám hiểm xưa: loại mồi Vua Cá thích, nơi nó nghỉ trưa và giờ nó ra khỏi hang. Mỗi thuyền phải đi qua ba khúc sông, bắt các loài cá chỉ đường và giải từng manh mối để mở khóa cần vàng. Nhưng một thuyền đối thủ do Bà Mũi Nhọn dẫn đầu cũng đang săn Vua Cá, muốn đem nó lên chợ. Lúc hoàng hôn, Vua Cá ra khỏi hang; thuyền bắt được sẽ cân, chụp ảnh và thả nó về sông như lời hứa với ông Chài Tư.","Ba khúc sông nối nhau: bến gỗ làng chài, hồ rộng giữa núi và cửa hang nơi sông chảy ra từ lòng núi. Từ trưa đến hoàng hôn, nắng vàng rồi đỏ rực. Trong cuốn sổ ông Chài Tư có bản đồ nổi của lưu vực sông.",[{"n":1,"title":"Cuốn sổ của ông Chài Tư","minutes":5,"optional":false,"goal":"Đọc trang đầu cuốn sổ, nhận nhiệm vụ.","beats":["Phim ngắn: bóng cá khổng lồ dưới nước.","Mỗi câu đúng mở một trang sổ.","Bản đồ nổi lưu vực sông chỉ ba khúc sông; chạm đúng tên khúc sông thì sổ mở trang."],"question_hook":"Cuốn sổ cũ; câu đọc hiểu ngắn mở từng trang.","reward":"Manh mối 1: loại mồi.","vocab":["legend","giant","clue","old","river basin","map"],"assets":["surv_letter","river_dock","river_cabin","fish_king_salmon","mini_indus_basin"]},{"n":2,"title":"Bến làng chài","minutes":5,"optional":false,"goal":"Bắt cá rô phi, cá trắm để đổi lấy mồi ruồi đặc biệt.","beats":["Ngư dân làng đổi mồi lấy cá.","Thuyền chèo và giỏ đan của làng chài nằm sẵn ở bến.","Một người lạ đi bộ qua bến làng chài, hỏi đường tới hồ giữa núi."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Mồi ruồi đặc biệt.","vocab":["trade","fly","village","rowboat","basket","stranger"],"assets":["fish_tilapia","fish_grass_carp","fish_bait","fish_bucket","river_boat_row","fish_basket","char_wanderer"]},{"n":3,"title":"Hồ giữa núi","minutes":5,"optional":false,"goal":"Câu cá hồi vân để biết nơi Vua Cá nghỉ trưa (manh mối 2).","beats":["Cá hồi vân bơi về hướng Vua Cá.","Nâng cần carbon sau 3 câu đúng.","Hồ giữa núi nhìn thấy đáy: đá nào, cá nào đọc đúng tên mới thấy."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Manh mối 2 + cần carbon.","vocab":["lake","rest","follow","trout","clear water","rock"],"assets":["fish_rainbow_trout","river_boat_aluminium","hdri_noon","mini_clear_river"]},{"n":4,"title":"Cuộc đua với Bà Mũi Nhọn","minutes":5,"optional":false,"goal":"Thuyền đối thủ chặn đường: vượt lên trước bằng câu trả lời đúng.","beats":["Thuyền đối thủ do máy chủ điều khiển.","Câu đúng = tăng tốc chèo."],"question_hook":"Câu hỏi trên mái chèo; mỗi câu đúng vượt lên một đoạn.","reward":"Đến cửa hang trước.","vocab":["race","ahead","rival","fast"],"assets":["river_boat_row","kayak_paddle","river_cliff"]},{"n":5,"title":"Cửa hang","minutes":5,"optional":false,"goal":"Giải manh mối 3 (giờ Vua Cá ra), nâng cần vàng.","beats":["Manh mối là câu đố giờ giấc bằng tiếng Anh.","Cần vàng cho thuyền giải xong."],"question_hook":"Câu đố hiện trên vách hang; câu dạng điền từ.","reward":"Cần vàng.","vocab":["cave","time","o'clock","gold"],"assets":["river_cave","fish_rod","surv_letter"]},{"n":6,"title":"Hoàng hôn: Vua Cá Hồi","minutes":5,"optional":false,"goal":"Vua Cá ra khỏi hang: săn, cân, chụp ảnh, thả về sông.","beats":["Vua Cá cần 3 câu đúng liên tiếp, câu cuối khó nhất.","Cả lớp cổ vũ; MVP là người kéo được Vua Cá hoặc cá nặng nhất.","Trước khi Vua Cá Hồi hiện ra, một con cá chép vàng hiếm bơi qua: ghi lại đặc điểm của nó."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Danh hiệu \"Người Gặp Vua Cá\"; ảnh lưu vào sổ ông Chài Tư.","vocab":["king","catch","photo","let go","golden carp","rare"],"assets":["fish_king_salmon","fish_scale","hdri_sunset","anim_pull_fish","anim_cheer","fish_golden_carp"]},{"n":7,"title":"Chặng phụ: Con của Vua Cá","minutes":5,"optional":true,"goal":"Kéo dài: đàn cá hồi nhỏ theo sau Vua Cá.","beats":["Bắt và thả đàn cá nhỏ."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["baby","family"],"assets":["fish_rainbow_trout"]},{"n":8,"title":"Chặng phụ: Trang sổ mới","minutes":5,"optional":true,"goal":"Viết trang sổ mới kể lại cuộc săn.","beats":["Trang sổ được ông Chài Tư dán vào sổ cũ."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.","reward":"Huy hiệu \"Thợ Săn Truyền Thuyết\".","vocab":["finally","amazing","we"],"assets":["surv_letter"]}],{"note":"Ba khúc sông = ba khu; thuyền đi theo thứ tự, lớp đông thì xuất phát so le 30 giây."},["anim_cheer","anim_pull_fish","char_wanderer","fish_bait","fish_basket","fish_bucket","fish_golden_carp","fish_grass_carp","fish_king_salmon","fish_rainbow_trout","fish_rod","fish_scale","fish_tilapia","hdri_noon","hdri_sunset","kayak_paddle","mini_clear_river","mini_indus_basin","river_boat_aluminium","river_boat_row","river_cabin","river_cave","river_cliff","river_dock","surv_letter"]]]$j$::jsonb) e
